// ==========================================
// ⚙️ KONFIGURATION: GABEN-DETAILS HIER EINTRAGEN
// ==========================================
const gabenName = "Husten und Jucken (Aphasma)";
const aepKosten = 8;
const macroLink = "@UUID[Compendium.dsk-havena-und-umland.makros.Macro.MWaPOIMjVSzJGNiv]{Husten und Jucken wirken}";
const iconBild = "https://assets.forge-vtt.com/644fbc20a9e089e2ef894956/modules/dsk-core/icons/journal/image-440.webp"; // Standard Aphasma Icon
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (!globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }
    if (!globalThis.DSK) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");

    // --- 2. WIRKENDEN AKTEUR ERMITTELN ---
    let wirkenderActor = null;
    if (typeof actor !== "undefined" && actor) wirkenderActor = actor; 
    else if (typeof testData !== "undefined" && testData && testData.speaker) wirkenderActor = game.actors.get(testData.speaker.actor);
    if (!wirkenderActor) wirkenderActor = canvas.tokens.controlled[0]?.actor;
    if (!wirkenderActor) wirkenderActor = game.user.character;

    if (!wirkenderActor) return ui.notifications.warn("Luna sagt 🌙: Ich konnte den Wirkenden nicht finden!");

    // --- 3. ROBUSTE QS-ERMITTLUNG (Der Panzerglas-Schutz!) ---
    let ermittelteQS = 1;
    let rollData = (typeof testData !== "undefined" && testData) ? testData : ((typeof args !== "undefined" && args[0]) ? args[0] : null);

    if (rollData && (rollData.qualityStep !== undefined || rollData.result?.QL !== undefined)) {
        ermittelteQS = Number(rollData.qualityStep || rollData.result?.QL || 1);
    } else {
        // FALLBACK: Das Makro sucht die letzte Probe im Chat und liest die QS aus!
        const lastRollMsg = game.messages.contents.slice().reverse().find(m => 
            m.speaker?.actor === wirkenderActor.id && 
            m.content && 
            m.content.includes("Qualitätsstufe")
        );
        if (lastRollMsg) {
            const qsMatch = lastRollMsg.content.match(/Qualitätsstufe(?:[^0-9]+)(\d+)/i);
            if (qsMatch && qsMatch[1]) {
                ermittelteQS = Number(qsMatch[1]);
            }
        }
    }

    // --- 4. AKTUELLE AeP AUSLESEN & PRÜFEN ---
    const currentAeP = foundry.utils.getProperty(wirkenderActor, "system.stats.AeP.value") || 0;

    let htmlInhalt = "";
    let topHeader = "";

    if (currentAeP < aepKosten) {
        topHeader = "Fehlschlag";
        await wirkenderActor.update({ "system.stats.AeP.value": 0 });
        htmlInhalt = `
            <p style="margin-bottom: 8px;"><b>${wirkenderActor.name}</b> hat versucht, die Gabe zu wirken.</p>
            <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
            <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b> Die Kraft reicht nicht aus.</p>
            <p style="margin-bottom: 8px;">Die restlichen <b>${currentAeP} AeP</b> wurden verbraucht, aber die Gabe schlägt fehl.</p>
        `;
    } else {
        topHeader = "Wirkungsbeginn"; 

        // Die ermittelte QS wird für das Wirkungs-Makro sicher abgespeichert
        await wirkenderActor.setFlag("world", "letzteGabenQS", ermittelteQS);
        await wirkenderActor.update({ "system.stats.AeP.value": currentAeP - aepKosten });

        htmlInhalt = `
            <p style="margin-bottom: 8px;"><b>${wirkenderActor.name}</b> hat die Gabe gewirkt.</p>
            <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
            <p style="margin-bottom: 8px; color: #76301b;"><b>Kosten:</b> Die AeP in Höhe von <b>${aepKosten}</b> sind abgezogen worden.</p>
            <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
            <p style="margin-bottom: 8px;">Bitte markiere (Target) dein Ziel und klicke hier:</p>
            <span style="font-size: 15px;">${macroLink}</span>
        `;
    }

    // --- 5. CHAT-NACHRICHT BAUEN & SENDEN ---
    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
        <div style="font-family: 'Signika', sans-serif;">
            <div class="dskbox1">
                <p style="display:flex; gap:8px; align-items:center; margin:0;"><img src="${iconBild}" style="width:28px;"><b style="font-size:1.05em;">${topHeader}</b></p>
                <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${gabenName}</p>
            </div>
            <div class="dskbox2" style="margin-top:10px; text-align: center;">${htmlInhalt}</div>
        </div>`
    });
})();
